-- name: ListStoreLineRanking :many
SELECT t4.store_code, t4.lines, t4.quantity, t4.rank
FROM (
    SELECT t3.store_code AS store_code, t3.lines AS lines, t3.quantity AS quantity, t3.rank AS rank
    FROM (
        SELECT t2.store_code, t2.lines, t2.quantity, rank() OVER (ORDER BY t2.lines DESC) AS rank
        FROM (
            SELECT t1.store_code AS store_code, count(*) AS lines, coalesce(sum(t1.quantity), 0)::int8 AS quantity
            FROM sales_lines AS t1
            WHERE ((sqlc.narg(date_from)::date IS NULL) OR (t1.sales_date >= sqlc.narg(date_from)::date))
            GROUP BY t1.store_code
        ) AS t2
    ) AS t3
) AS t4
ORDER BY t4.rank, t4.store_code
LIMIT 51;
